/* Original beginner curriculum. Each session pairs reading with observation and recall. */
const stages = [
 {name:'Maths & statistics',short:'The foundations',icon:'spark',color:'#7355c5',bg:'#f0eafa',description:'Get comfortable with numbers, questions and uncertainty.'},
 {name:'Excel',short:'Think in spreadsheets',icon:'grid',color:'#328366',bg:'#e8f4ed',description:'Turn a sheet of numbers into a useful answer.'},
 {name:'Python',short:'Your first lines of code',icon:'code',color:'#387db5',bg:'#e8f1fb',description:'Make analysis repeatable with small, understandable steps.'},
 {name:'SQL & databases',short:'Ask your data',icon:'database',color:'#c3634b',bg:'#fbece6',description:'Find, combine and summarize information in tables.'},
 {name:'Power BI & Tableau',short:'Make the picture clear',icon:'chart',color:'#b47e25',bg:'#fcf1d9',description:'Choose one dashboard tool and learn the ideas they share.'},
 {name:'Prepare & validate',short:'Build trustworthy data',icon:'filter',color:'#357f80',bg:'#e7f3f2',description:'Clean carefully. Check what changed. Trust your results.'},
 {name:'Explore & model',short:'Find the useful patterns',icon:'search',color:'#bd6865',bg:'#fcece9',description:'Move from a business question to evidence you can explain.'},
 {name:'Machine learning',short:'An optional next step',icon:'nodes',color:'#6478bc',bg:'#edf0fc',description:'Understand prediction, evaluate it honestly and know its limits.',optional:true},
 {name:'Data storytelling',short:'Make insights matter',icon:'message',color:'#977140',bg:'#f7efdf',description:'Explain the evidence and recommend a useful next step.'}
];
const lessons=[];
function L(stage,title,summary,points,example,task,quiz,takeaway,diagram='bars',code=''){
 lessons.push({id:lessons.length,stage,title,summary,points,example,task,quiz:{question:quiz[0],options:quiz[1],correct:quiz[2],explanation:quiz[3]},takeaway,diagram,code});
}
// STAGE 1 — a true zero-knowledge starting point.
L(0,'So, what is a data analyst?','Start with a question. Use evidence to help someone make a better decision.',[
 ['Data is recorded information.','An order date, a product name and an amount paid are all data. A dataset is a collection of these records.'],
 ['Analysis begins with a decision.','“Our sales are down” is a starting point. “Which product needs attention this month?” is a question you can investigate.'],
 ['A row describes one thing.','In an orders table, one row might mean one order. A column describes an attribute, such as price. Confirm what a row means before counting.'],
 ['An analyst follows a loop.','Ask a question, collect data, clean it, analyze it, explain the finding and check what happens after the decision.'],
 ['Tools support your thinking.','Excel, SQL, Python and dashboards help with different parts of the loop. You do not need all of them to ask your first useful question.']
],['A tiny café question','A café sold 20 coffees on Monday and 30 on Tuesday. You can report that Tuesday sold 10 more. Before explaining why, ask about opening hours, promotions and missing orders. More sales alone does not tell you the cause.'], 'Write one question a café owner could act on. Name the decision, the data you would need and what one row would represent.', ['Which is the most useful starting point?',['Choose the fanciest chart','Define the question and decision','Learn every tool before asking questions'],1,'A question gives the analysis a purpose and helps you choose relevant data.'], 'An analyst connects a clear question to trustworthy evidence and a practical decision.','workflow');
L(0,'Percentages without the panic','Learn the difference between a share, a change and a percentage point.',[
 ['A percentage is a part of 100.','If 8 of 40 customers return, the returning-customer share is 8 ÷ 40 × 100 = 20%.'],
 ['Growth compares with the starting value.','Percentage change = (new − old) ÷ old × 100. Always name the starting period.'],
 ['Percentage points compare percentages.','A rate rising from 20% to 25% increases by 5 percentage points. Its relative increase is 25%, because 5 ÷ 20 = 25%.'],
 ['Ratios compare quantities.','A ratio of 2 returned orders to 50 orders is 2:50, or a 4% return rate. Keep numerator and denominator consistent.'],
 ['Zero needs special care.','Growth from zero has no ordinary percentage-change result because division by zero is undefined. Report the absolute change instead.']
],['Sales went from 80 to 100','The absolute increase is 20. The relative increase is 20 ÷ 80 = 25%. Dividing by the new value would answer a different question. A rate changing from 80% to 100% is instead a 20-percentage-point rise.'], 'Calculate growth from 200 to 250. Then describe a conversion rate moving from 4% to 5% using both percentage points and relative change.', ['Sales increase from 50 to 60. What is the growth rate?',['10%','20%','60%'],1,'The increase is 10, divided by the original 50: 10 ÷ 50 = 20%.'], 'Name the denominator and distinguish relative change from percentage points.','bars');
L(0,'Meet the average family','Mean, median and mode answer different questions about a typical value.',[
 ['Mean shares the total equally.','Add the values and divide by their count. It is useful when every observation should contribute to the total.'],
 ['Median is the middle after sorting.','For an even number of observations, average the two middle values. The median is less sensitive to extremely large or small values.'],
 ['Mode is the most frequent value.','It can describe categories as well as numbers. A dataset may have more than one mode, or no useful single mode.'],
 ['Weighted means respect group sizes.','Multiply each value by its weight, add the results and divide by total weight. Averaging two group averages equally can mislead.'],
 ['Choose for the question.','For a typical salary in a skewed group, median can be more representative. To calculate total payroll from headcount, the mean is useful.']
],['Five café bills: 4, 5, 5, 6, 30','The total is 50, so the mean is 10. The sorted middle value is 5, so the median is 5. The mode is also 5. The large bill pulls the mean upward; it does not make the mean mathematically wrong.'], 'Find the mean and median of 2, 3, 4, 5, 26. Explain which better describes a typical small purchase and why.', ['For 4, 5, 5, 6, 30, what is the median?',['5','10','30'],0,'After sorting, the third of five values is 5.'], 'An average is a choice. Match it to the question and inspect the distribution.','distribution');
L(0,'Look beyond the average','Spread, distributions and outliers reveal what a single number hides.',[
 ['Range shows the full span.','Subtract the minimum from the maximum. It is easy to understand but depends entirely on the two extremes.'],
 ['Standard deviation describes spread.','It summarizes variation around the mean in the original units. Variance uses squared units. Sample and population formulas differ.'],
 ['Percentiles locate a value.','The 90th percentile is a cutoff at or below which roughly 90% of observations fall. Calculation conventions can differ slightly.'],
 ['Quartiles split the sorted data.','Q1 and Q3 mark roughly 25% and 75%. The interquartile range is Q3 − Q1, describing the middle half.'],
 ['Outliers are signals to investigate.','A very high order could be an entry error or a real bulk purchase. Do not delete it simply because it is unusual.'],
 ['Distributions have shapes.','A long right tail often makes the mean larger than the median. A histogram groups numeric values into intervals to reveal shape.']
],['Same mean, different experience','Delivery times of 9, 10, 11 have mean 10. Times of 1, 10, 19 also have mean 10, but vary much more. A promise based only on the mean hides the second service’s inconsistency.'], 'Sketch two groups with the same average but different spread. Write one sentence explaining why a customer would care.', ['Two services have the same mean delivery time. What helps compare reliability?',['The company name','The spread and upper percentiles','Only the mean again'],1,'Spread and tail percentiles reveal inconsistency and unusually long waits.'], 'Report typical values together with variation and unusual observations.','distribution');
L(0,'Samples, probability & uncertainty','A sample offers evidence about a population, with limits.',[
 ['A population is the group of interest.','A sample is the subset you observe. Surveying only happy customers will not represent every customer.'],
 ['Probability describes uncertainty.','Values run from 0 to 1. Conditional probability describes a chance within a specified group, such as returns among online purchases.'],
 ['Sampling method matters.','Random sampling helps reduce selection bias. A huge convenience sample can still be systematically biased.'],
 ['An estimate is not exact.','Sample results vary. A confidence interval describes an estimation method’s uncertainty under assumptions; it does not capture every source of bias.'],
 ['Interpret confidence carefully.','A 95% confidence procedure covers the fixed population value in about 95% of repeated samples under its assumptions. Avoid treating it as a guarantee about one result.']
],['A survey with a blind spot','You ask 100 customers in the café whether opening at 6 a.m. matters. People who cannot visit during current hours are missing. Increasing the in-store sample to 1,000 does not automatically fix that blind spot.'], 'Design a better survey about opening hours. Name who might be missing and how you would reach them.', ['What does a larger sample automatically fix?',['Every source of bias','Random sampling variation can decrease; bias may remain','An unclear business question'],1,'More observations can improve precision, but selection and measurement problems can persist.'], 'Ask who is missing before trusting a precise-looking number.','sample');
L(0,'Tests, experiments & cause','Learn what evidence can support a claim that something made a difference.',[
 ['A hypothesis test starts with a baseline claim.','For example, the new checkout and old checkout have equal conversion rates. Choose your comparison and measurement before examining results.'],
 ['A p-value is conditional evidence.','Under the null model, it measures how unusual results at least as extreme as yours would be. It is not the probability that the null hypothesis is true.'],
 ['Size matters as well as significance.','A tiny improvement can be statistically detectable but commercially unimportant. Report the effect size, uncertainty and relevant costs.'],
 ['Random assignment supports causal inference.','In an A/B test, comparable groups receive different versions. Check sample size, assignment, measurement and the chosen test duration.'],
 ['Correlation is not a causal explanation.','Ice cream sales and swimming both rise in warm weather. Temperature is a possible common cause. Regression can describe relationships, but does not remove all confounding.']
],['Did a new menu improve orders?','A café changes its menu during a holiday week and sees higher sales. The holiday is a competing explanation. Randomly assigning comparable customers to menu versions would offer stronger evidence, if operationally feasible.'], 'Write a hypothesis for testing two checkout designs. Choose the primary metric and one risk metric, such as errors or refunds.', ['Why does a before/after increase alone not prove causation?',['Numbers cannot be compared','Other factors may have changed too','Experiments never work'],1,'Seasonality, promotions or different customer groups can explain the change.'], 'Connect a claim to its study design, effect size and uncertainty.','experiment');
// STAGE 2
L(1,'Your first useful spreadsheet','Understand cells, tables and the meaning of a row.',[
 ['A cell has a position and a value.','A1 means column A, row 1. Text, numbers and dates behave differently; a number stored as text may not calculate correctly.'],
 ['Use one header row.','Give every column a clear name and keep one type of information per column. Avoid merged cells inside analysis tables.'],
 ['Keep each row at a consistent grain.','If one row is an order line, the order can appear on multiple rows. Counting rows would count lines, not distinct orders.'],
 ['Turn ranges into tables.','Excel tables expand as rows are added and support readable column references. Keep raw inputs separate from your summary.'],
 ['Formatting changes appearance.','Displaying two decimals does not necessarily round the stored value. Dates need consistent interpretation, especially ambiguous day/month values.']
],['A tidy order table','Use columns OrderID, OrderDate, Product, Quantity and UnitPrice. Put one product line per row. Do not insert a “monthly total” row into the raw orders; build that summary elsewhere.'], 'Create a five-row order table. Write what one row represents and identify which columns should be numeric, text and dates.', ['An order with three product lines occupies three rows. COUNT of rows gives…',['Three orders','Three order lines','Three customers'],1,'The table grain is an order line. Count distinct OrderID values for orders.'], 'Good structure makes every later spreadsheet task safer.','sheet');
L(1,'Sort, filter & protect your inputs','Find the relevant rows without breaking their relationships.',[
 ['Sorting changes row order.','Sort the entire table together so values stay connected. Sorting only the price column can pair prices with the wrong products.'],
 ['Filtering hides rows from view.','It does not delete them. Be aware that many ordinary formulas still include hidden rows; SUBTOTAL can support filtered summaries.'],
 ['Data validation limits entry.','Use lists for categories and rules for valid quantities or dates. Validation reduces mistakes but does not replace checking imported data.'],
 ['Conditional formatting highlights rules.','Flag missing IDs, repeated values or amounts above a threshold. A colored cell is a cue to investigate, not proof of an error.'],
 ['Keep originals recoverable.','Preserve a raw copy and record changes. Review duplicates using a meaningful key before removing rows.']
],['Spot a suspicious quantity','A quantity of 500 may stand out among values of 1–5. Highlight it with conditional formatting, then check the original order. It could be a wholesale purchase rather than a typo.'], 'Filter your order table to one product, then sort by date. Add a quantity rule that permits positive whole numbers.', ['What happens when you filter a table?',['Hidden rows are deleted','Rows outside the condition are hidden','All formulas ignore hidden rows'],1,'Filtering changes the view. Formula behavior depends on the function used.'], 'Use sorting and filters to inspect data; use validation to reduce input mistakes.','sheet');
L(1,'Formulas that do the heavy lifting','Start with totals, counts, references and error checks.',[
 ['Formulas begin with an equals sign.','SUM adds values, AVERAGE calculates the mean, and MIN/MAX find extremes. Parentheses control the order of operations.'],
 ['Counting functions differ.','COUNT counts numeric cells. COUNTA counts nonempty cells, including text. Formula-generated empty text can need extra care.'],
 ['Relative references move when copied.','A2 becomes A3 on the next row. $A$2 stays fixed; $A2 fixes the column and A$2 fixes the row.'],
 ['Calculate at the correct level.','Line revenue is quantity × unit price. Total line revenues rather than multiplying totals of unrelated columns.'],
 ['Understand an error before hiding it.','IFERROR can replace an error with a message. Replacing every error with zero may conceal missing prices or broken references.']
],['Calculate line revenue','If Quantity is in D2 and UnitPrice is in E2, =D2*E2 gives revenue for that line. Copy down, then use =SUM(F2:F6). If a tax rate is stored in H1, use =$H$1 when it must stay fixed.'], 'Write formulas for total revenue, average quantity and highest unit price. Explain why the tax cell needs an absolute reference.', ['Which function counts nonempty text and numeric cells?',['COUNT','COUNTA','MAX'],1,'COUNTA counts nonempty cells; COUNT is for numeric values.'], 'Know what a function counts and how its references behave when copied.','sheet','=D2*E2\n=SUM(F2:F6)\n=AVERAGE(D2:D6)\n=F2*$H$1');
L(1,'Answer questions with conditions','Use IF, conditional summaries and lookups to connect information.',[
 ['IF chooses between two outputs.','For example, label a line “Large” if its revenue is at least 100. AND requires all conditions; OR requires at least one.'],
 ['SUMIFS totals matching rows.','COUNTIFS counts matching rows, and AVERAGEIFS averages them. Keep criteria ranges aligned with the values being summarized.'],
 ['Lookups connect a key to an attribute.','XLOOKUP can find a ProductID and return its category. Use an explicit missing-result message. INDEX with MATCH is another useful pattern.'],
 ['Matching keys should be clean.','Spaces, inconsistent types and duplicate lookup keys can cause unexpected results. A lookup returning one match does not prove the relationship is unique.'],
 ['Text and dates need preparation.','TRIM, LEFT, RIGHT and related functions help standardize text. YEAR, MONTH and date arithmetic help create time-based summaries.']
],['Revenue for coffee','With Product in C2:C6 and Revenue in F2:F6, =SUMIFS(F2:F6,C2:C6,"Coffee") totals coffee revenue. =COUNTIFS(C2:C6,"Coffee") counts coffee lines, which may differ from coffee orders.'], 'Build an IF label for revenue above 100. Then use a lookup to add a category from a separate product table.', ['A lookup table has two different categories for the same ProductID. What should you do?',['Trust whichever result appears first','Investigate and resolve the conflicting key','Change every ID randomly'],1,'The key should identify a reliable category. A first match can hide conflicting records.'], 'Conditional formulas are useful only when the criteria and keys are trustworthy.','sheet','=IF(F2>=100,"Large","Standard")\n=SUMIFS(F2:F6,C2:C6,"Coffee")\n=XLOOKUP(C2,Products[ProductID],Products[Category],"Not found")');
L(1,'From rows to a dashboard','Summarize with pivot tables, then choose charts that answer a question.',[
 ['Pivot tables group and summarize.','Place categories in Rows, dates in Columns and revenue in Values. Check whether the value calculation is SUM or COUNT.'],
 ['Refresh when inputs change.','A report may still show old data until its pivot or connection is refreshed. Verify the source range includes new records.'],
 ['Choose a chart for the comparison.','Bars compare categories, lines show time trends and scatter plots show relationships. Avoid decoration that makes values harder to compare.'],
 ['Slicers make filters visible.','A dashboard reader should see the active period and category. A dramatic total without its filter context can mislead.'],
 ['Reconcile your summary.','Check that the pivot grand total matches a separately calculated total. Then test a few categories by hand.']
],['One question, one view','To answer “Which product brought in the most revenue?”, build a product-by-revenue pivot and a sorted bar chart. Add a month slicer and label the metric as revenue, not profit.'], 'Sketch a small dashboard with one KPI, one trend chart and one product comparison. State the question each element answers.', ['A pivot displays COUNT of Revenue instead of SUM. What should you check first?',['The font','The value setting and whether amounts are numeric','The worksheet name'],1,'Incorrect aggregation or text-formatted numbers can produce counts instead of totals.'], 'A dashboard is a set of answers, not a collection of decorative charts.','bars');
L(1,'Clean once, repeat with Power Query','Create a transformation process you can refresh instead of repeating manually.',[
 ['Power Query records transformations.','Connect to a source, transform it and load the result. Steps can be rerun when new source data arrives.'],
 ['Set data types deliberately.','Check date locale, decimal interpretation and text IDs with leading zeros. Automatic type detection can be wrong.'],
 ['Merge and append solve different problems.','Merge adds columns by matching keys. Append stacks compatible rows from similar tables, such as monthly sales files.'],
 ['Reshape when headers contain data.','Unpivot month columns into a Month column and a Value column. This often makes grouping and charting easier.'],
 ['Validate after each major change.','Compare row counts, totals and unmatched keys. Keep step names understandable so another person can follow the process.']
],['Monthly files become one table','January and February files share the same columns. Append their rows, standardize Product names and set Revenue to a numeric type. Refresh when March is added, then compare the combined total with the source files.'], 'Describe a repeatable cleaning process for three monthly files. Include one type check and one total check.', ['You need to stack January rows below February rows. Use…',['Append','Merge by product','A chart filter'],0,'Append combines rows with compatible structures. Merge joins attributes using matching keys.'], 'A repeatable transformation is easier to audit than a series of undocumented edits.','workflow');
// STAGE 3
L(2,'Python without the mystery','Learn how small instructions turn into a repeatable analysis.',[
 ['Python runs instructions in order.','A script is a saved set of instructions. A notebook groups code and explanations into cells, but running cells out of order can create confusing state.'],
 ['Variables name values.','revenue = 120 stores a value under a name. Common types include integers, decimals, strings and booleans.'],
 ['Operations depend on type.','Adding two numbers calculates a sum. Adding two strings joins text. Convert imported values carefully before arithmetic.'],
 ['Lists hold sequences.','A list such as [4, 5, 6] stores multiple values. Python indexes start at zero, so the first item is at position 0.'],
 ['Readable names matter.','Use clear names and short comments explaining intent. Restart and run a notebook from top to bottom to check reproducibility.']
],['Your first calculation','Store 20 coffees sold and a price of 3. Multiply them to get revenue of 60. This simple calculation becomes useful when repeated across thousands of records with validated inputs.'], 'Read the code below aloud in plain English. Change the quantity to 25 and predict the output before running it.', ['What does the first index of a Python list use?',['0','1','The length of the list'],0,'Python sequences use zero-based indexing.'], 'Start with small steps whose inputs and outputs you can explain.','code','quantity = 20\nprice = 3\nrevenue = quantity * price\nprint(revenue)  # 60');
L(2,'Collections, decisions & functions','Give your code structure without making it complicated.',[
 ['Choose a collection for its job.','Lists are ordered and editable. Tuples are ordered and generally fixed. Sets hold unique values. Dictionaries map keys to values.'],
 ['Conditions choose a branch.','if, elif and else run different instructions based on boolean expressions. Indentation defines the block.'],
 ['Loops repeat a task.','A for loop visits items in a collection. Keep the calculation understandable before trying to make it faster.'],
 ['Functions name a reusable operation.','Parameters supply inputs and return supplies an output. Separate calculation from printing to make functions easier to reuse.'],
 ['Handle failures intentionally.','Catch specific expected exceptions. A broad catch that ignores every error can quietly produce incomplete results.']
],['A reusable growth calculation','A growth function can return (new − old) / old when old is nonzero. When old is zero, return a clearly documented missing result or raise an informative error instead of inventing a growth rate.'], 'Write the plain-language steps for a function that totals a list of order amounts. What should happen for an empty list?', ['Which collection maps a product ID to a price?',['Dictionary','A single boolean','A comment'],0,'A dictionary stores key-value mappings such as product ID to price.'], 'Use clear structures and small functions to make analysis easier to inspect.','code','prices = {"coffee": 3, "tea": 2}\n\ndef line_revenue(quantity, price):\n    return quantity * price\n\nprint(line_revenue(4, prices["coffee"]))');
L(2,'Meet pandas and your first dataset','Use labeled rows and columns to work with real tables.',[
 ['pandas provides table-like structures.','A DataFrame is a two-dimensional table. A Series is a labeled one-dimensional set of values, often a column.'],
 ['Load, then inspect.','read_csv and read_excel import common files. Use head, shape, info and describe to inspect rows, types, missing values and summary statistics.'],
 ['NumPy underpins many numeric operations.','Arrays support efficient calculations on collections. You can begin useful pandas work without advanced array mathematics.'],
 ['Select columns explicitly.','df["revenue"] selects a column; df[["product", "revenue"]] selects a table of two columns. Use .loc for label-based selection and filtering.'],
 ['Do not trust inferred types blindly.','An ID may look numeric but represent a label. A date may still be text. Confirm assumptions before analysis.']
],['Inspect before calculating','After importing orders.csv, check how many rows there are and whether Revenue is numeric. Look at a few records and confirm whether one row means an order or an order line.'], 'Write three checks you would perform immediately after loading an unfamiliar file. Explain what each check could reveal.', ['What should you do immediately after importing a file?',['Assume the types are correct','Inspect rows, types and table grain','Delete all missing rows'],1,'Inspection reveals structural and quality issues before they distort results.'], 'Importing data successfully does not mean the data is ready for analysis.','sheet','import pandas as pd\n\norders = pd.read_csv("orders.csv")\nprint(orders.head())\nprint(orders.shape)\nprint(orders.info())');
L(2,'Filter, group, join & reshape','Use a few table operations to answer many business questions.',[
 ['Boolean filters select rows.','Create a condition such as revenue > 100 and use .loc to keep matching records. Parenthesize conditions combined with & or |.'],
 ['Groupby summarizes categories.','Group by product and calculate revenue totals. Name the metric clearly and check whether missing grouping values are included.'],
 ['Merge combines matching records.','Choose keys and join type deliberately. Use validation such as many_to_one when adding a unique product attribute to many order lines.'],
 ['Concatenation stacks compatible data.','Use concat for monthly files with consistent columns. Check for duplicate imports and incompatible types.'],
 ['Pivot and melt reshape tables.','Pivot moves categories into columns; melt brings repeated columns into rows. Choose the shape that matches your next analysis.']
],['Category revenue without inflation','Merge order lines with a products table on ProductID. The products table should have one row per ProductID. A many-to-one validation can flag duplicate keys before they multiply the order rows.'], 'Explain how you would produce monthly revenue by category from orders and products tables. Include a check after the merge.', ['A merge unexpectedly doubles total revenue. A likely cause is…',['Duplicate matching keys','A clearer chart title','A renamed notebook'],0,'Multiple matches can duplicate order rows and inflate totals.'], 'After combining tables, verify both row counts and business totals.','join','enriched = orders.merge(\n    products, on="ProductID", how="left",\n    validate="many_to_one"\n)\nsummary = enriched.groupby("Category")["Revenue"].sum()');
L(2,'Clean data and make your first plots','Handle missing values, dates and visual exploration carefully.',[
 ['Missing is different from zero.','isna reveals missing values. dropna and fillna change the data, so choose a rule based on what missing means.'],
 ['Convert with visible failure checks.','to_numeric or to_datetime can expose invalid values. If coercing errors to missing, count and inspect those new missing values.'],
 ['Standardize text carefully.','Trim spaces and normalize case for category matching. Preserve original fields when transformations could lose important meaning.'],
 ['Visualize to inspect patterns.','Matplotlib gives direct plotting control. Seaborn provides convenient statistical chart patterns. Label axes, units and the source period.'],
 ['Check the plot against the table.','A line chart may connect missing periods misleadingly. Sort dates and inspect whether gaps represent no activity or absent data.']
],['An invalid date should not disappear silently','Converting “2026-02-30” to a date fails because the day is impossible. If conversion turns it into a missing date, log how many records failed and investigate their original text.'], 'Choose a histogram for order value and a line chart for monthly revenue. Explain what each could reveal and what its axes represent.', ['A missing revenue amount should always become zero.',['True','False; first understand why it is missing','Only when the chart looks better'],1,'Unknown revenue and a genuine zero sale have different meanings.'], 'Cleaning choices are analytical decisions. Make them visible.','bars','orders["OrderDate"] = pd.to_datetime(\n    orders["OrderDate"], errors="coerce"\n)\nprint(orders["OrderDate"].isna().sum())');
L(2,'Make an analysis repeatable','Connect sources and leave a process someone else can run.',[
 ['A package adds reusable capabilities.','Use a project environment and record dependencies. This helps avoid “works on my computer” differences.'],
 ['SQL can supply a DataFrame.','pandas can load query results through a suitable database connection. Keep credentials out of notebooks and shared files.'],
 ['APIs return structured responses.','Many use JSON. Check request status, pagination, field definitions and rate limits before assuming you have all records.'],
 ['Separate inputs, transformations and outputs.','Use named steps or functions. Export a clean CSV or report with enough metadata to understand its period and units.'],
 ['Re-run from a clean state.','Check row counts and totals automatically, save clear instructions and use Git to track meaningful source changes. Never commit secrets.']
],['The monthly report handover','A colleague should be able to supply a new source file, run the documented process and reproduce the report. Include required packages, source expectations, validation checks and the output location.'], 'Draft a five-line README describing your analysis inputs, how to run it, its outputs and two limitations.', ['What most improves reproducibility?',['Running notebook cells in a remembered order','Documented inputs, dependencies and a clean full run','Saving only a screenshot'],1,'A repeatable process requires both source context and a consistent execution path.'], 'A useful analysis should be reproducible, understandable and safe to share.','workflow');
// STAGE 4
L(3,'Understand the database before querying','Tables are connected by keys, and their grain determines what you can count.',[
 ['A relational database stores related tables.','Customers, Orders and Products may be separate. A schema organizes objects and defines their structure.'],
 ['A primary key identifies a row.','It should uniquely identify a record. A foreign key refers to a record in another table, such as Orders.CustomerID.'],
 ['Relationships have cardinality.','One customer can have many orders. Many-to-many relationships often need a linking table and special care with aggregation.'],
 ['Data types shape operations.','Dates support date calculations, numeric fields support arithmetic and text IDs may contain leading zeros.'],
 ['NULL means missing or unknown.','Use IS NULL or IS NOT NULL to test it. A comparison such as column = NULL does not behave like equality with an ordinary value.']
],['Customers and orders','Customers has one row per CustomerID. Orders has one row per OrderID and a CustomerID linking to its buyer. The number of customer rows and order rows answer different questions.'], 'Draw two small tables for customers and orders. Mark the primary keys and show the one-to-many relationship.', ['Which condition finds missing customer IDs in SQL?',['CustomerID = NULL','CustomerID IS NULL','CustomerID = 0 always'],1,'NULL requires IS NULL. Zero may be a real value and is not the same as unknown.'], 'Read the schema and define one row before you write a query.','join');
L(3,'Select, filter & sort your first query','Ask for the columns and records needed to answer one question.',[
 ['SELECT chooses columns.','FROM names the source table. Use explicit columns in shared analysis so the result structure is clear.'],
 ['WHERE filters individual rows.','Use comparisons, IN for sets, BETWEEN for inclusive bounds and LIKE for text patterns. Parentheses clarify mixed AND/OR conditions.'],
 ['Dates need careful boundaries.','A timestamp includes a time. For a month, use a start-inclusive and next-month-exclusive range to include the whole final day.'],
 ['ORDER BY makes order explicit.','Without it, returned row order is not guaranteed. Add a stable tie-breaker when results need to be reproducible.'],
 ['DISTINCT removes repeated result combinations.','It can be useful, but should not conceal a faulty join. Row-limit syntax and some functions vary by database system.']
],['January orders only','Use OrderDate >= January 1 and OrderDate < February 1. This includes records on January 31 at 11 p.m., which a midnight end boundary could accidentally exclude.'], 'Describe a query for orders over 100 during January, showing OrderID, OrderDate and Revenue in descending revenue order.', ['What guarantees a query result is sorted?',['The table was sorted yesterday','ORDER BY','SELECT alone'],1,'Only an explicit ORDER BY specifies result ordering.'], 'Choose columns, filter intentionally and state the order you need.','code',"SELECT OrderID, OrderDate, Revenue\nFROM Orders\nWHERE Revenue > 100\n  AND OrderDate >= '2026-01-01'\n  AND OrderDate < '2026-02-01'\nORDER BY Revenue DESC, OrderID;");
L(3,'Summarize with groups and conditions','Move from individual records to useful totals.',[
 ['Aggregate functions summarize rows.','SUM, AVG, MIN and MAX operate on values. COUNT(*) counts rows; COUNT(column) counts non-NULL values in that column.'],
 ['GROUP BY defines summary groups.','Group by product for product revenue or by customer for customer spending. Understand what one output row will mean.'],
 ['WHERE and HAVING act at different stages.','WHERE filters rows before grouping. HAVING filters the resulting groups, such as groups with total revenue above 1,000.'],
 ['CASE creates conditional categories.','It can label an order or support conditional aggregation. Make branches mutually clear and consider an ELSE outcome.'],
 ['COALESCE chooses a fallback.','It returns the first non-NULL expression. Use zero only when missing truly means none, not when it means unknown.']
],['Products above 1,000 revenue','Filter to paid orders with WHERE, group by ProductID, sum Revenue and use HAVING SUM(Revenue) > 1000. Reversing row and group filters changes the question.'], 'Explain the difference between “orders above 100” and “customers whose total orders exceed 100.” Which requires grouping?', ['Which clause filters groups after aggregation?',['WHERE','HAVING','ORDER BY'],1,'HAVING applies conditions to groups; WHERE filters input rows.'], 'Always define the grain of both the input and the grouped output.','bars',"SELECT ProductID, SUM(Revenue) AS total_revenue\nFROM OrderLines\nWHERE Status = 'Paid'\nGROUP BY ProductID\nHAVING SUM(Revenue) > 1000;");
L(3,'Join tables without multiplying mistakes','Understand matched rows, unmatched rows and duplicate keys.',[
 ['INNER JOIN keeps matching combinations.','Rows without a match are excluded. That may be correct, but can silently drop records you intended to keep.'],
 ['LEFT JOIN preserves left-side rows.','Unmatched right-side fields become NULL. A later WHERE condition on those fields can unintentionally remove unmatched rows.'],
 ['Many matches produce many output rows.','If a key appears twice on each side, it can produce four joined combinations. Check key uniqueness before summing measures.'],
 ['Other joins have specific purposes.','FULL OUTER JOIN can retain unmatched rows from both sides where supported. CROSS JOIN forms every combination and grows quickly.'],
 ['UNION ALL stacks compatible results.','UNION removes duplicate result rows. Neither replaces a join that adds columns by matching keys.']
],['Keep products with no sales','Start from Products and LEFT JOIN order lines to list every product. Count a non-NULL order-line key, not COUNT(*), because a product without sales still contributes a preserved row.'], 'Use two small tables to predict the output of an INNER JOIN and a LEFT JOIN. Include one unmatched key and one duplicate key.', ['A LEFT JOIN can produce more rows than its left table when…',['A right-side key has multiple matches','The table has a clear title','There is an ORDER BY'],0,'Each matching combination produces a row. Multiple right-side matches can multiply left-side rows.'], 'Validate keys, unmatched records and totals whenever tables are joined.','join');
L(3,'CTEs and window functions','Break queries into readable steps and compare rows without collapsing them.',[
 ['A subquery supplies an intermediate result.','It can be used inside a larger query. A CTE names a temporary result for the duration of one statement.'],
 ['CTEs improve readability.','Separate cleaning, grouping and ranking into named stages. A CTE is not automatically a permanent table or a performance improvement.'],
 ['Window functions retain detail rows.','OVER defines the window. PARTITION BY splits rows into groups; ORDER BY defines a sequence within each group.'],
 ['Ranking functions handle ties differently.','ROW_NUMBER assigns distinct sequential numbers. RANK allows ties with gaps; DENSE_RANK allows ties without rank gaps.'],
 ['LAG and running totals compare across rows.','Specify ordering and appropriate window frames. Missing months need deliberate handling; previous row does not always mean previous calendar month.']
],['A running revenue total','First produce one row per month. Then sum monthly revenue over months in order, using a frame from the first row through the current row. Check missing months before interpreting month-over-month comparisons.'], 'Explain when you would use GROUP BY and when you would use a window function to compare each order with its customer’s total.', ['Which preserves each order row while calculating a customer total?',['Only GROUP BY CustomerID','SUM(...) OVER (PARTITION BY CustomerID)','DISTINCT on every column'],1,'Window aggregation adds a result to each row instead of collapsing the detail.'], 'Use grouped results for summaries and windows for context alongside detail.','code','SELECT Month, Revenue,\n  SUM(Revenue) OVER (\n    ORDER BY Month\n    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\n  ) AS running_revenue\nFROM MonthlyRevenue;');
L(3,'Dates, checks & efficient queries','Write queries that are correct, understandable and considerate of the database.',[
 ['Date and text functions vary.','Know your database dialect. Date truncation, interval arithmetic and string functions have different spellings across systems.'],
 ['Document metric definitions.','Specify time zone, refund treatment and whether revenue is gross or net. A correct query can still answer the wrong business definition.'],
 ['Indexes can speed some lookups.','They help suitable access patterns but cost storage and writes. Inspect a query plan rather than assuming every slow query needs another index.'],
 ['Reduce unnecessary work.','Select needed columns and filter relevant records. Applying a function to a filtered column can sometimes prevent efficient index use.'],
 ['Validate with independent checks.','Compare counts and totals, inspect edge cases and review a few source records. Use read-only access for analysis when available.']
],['A midnight reporting mismatch','Orders stored in UTC may belong to a different local day. Define the reporting time zone before calculating daily revenue. Then test records near midnight rather than only midday examples.'], 'Write a checklist for a monthly revenue query: definition, time boundary, NULL handling, joins, totals and performance.', ['A fast query with the wrong revenue definition is…',['Still a good answer','Incorrect for the business question','Fixed by adding an index'],1,'Correctness requires matching the business definition as well as valid SQL.'], 'The best query is correct first, clear second and efficient enough for its context.','workflow');
// STAGE 5
L(4,'Choose a dashboard tool and connect data','Power BI and Tableau share analytical ideas; you can learn one first.',[
 ['A dashboard supports a decision.','Begin with audience, question and update frequency. A daily operations dashboard needs different detail from a quarterly leadership report.'],
 ['Connect to a reliable source.','Files, databases and published data sources can feed reports. Know who maintains the source and what its fields mean.'],
 ['Connection modes have tradeoffs.','Imported or extracted data can be fast but need refreshing. Live or direct queries rely more on the source and its response time.'],
 ['Transform before visualizing.','Fix types, naming and structure. Keep a record of transformations rather than manually patching chart outputs.'],
 ['Start with one tool.','Choose either Power BI or Tableau for your first project. Learn shared concepts before trying to master both interfaces.']
],['A café owner’s morning report','The owner needs yesterday’s orders, revenue and an indication of unusual refunds. A simple daily refreshed report may serve this better than a complicated view with dozens of filters.'], 'Define one dashboard audience, its main decision, three metrics and an appropriate refresh frequency.', ['What should you define before arranging dashboard charts?',['The audience and decision','Every available animation','The brightest background'],0,'Purpose determines metrics, detail, layout and refresh requirements.'], 'A dashboard begins with the reader’s decision, not the tool’s chart gallery.','dashboard');
L(4,'Build a model that adds up','Understand facts, dimensions and relationships before creating measures.',[
 ['Fact tables store events or measurements.','An order-line fact table contains quantities and revenue at a defined grain. Keep that grain consistent.'],
 ['Dimension tables describe those events.','Products, customers and dates provide attributes for grouping and filtering. A dimension key should identify one relevant record.'],
 ['A star schema keeps relationships clear.','Dimensions connect to a central fact table. Avoid ambiguous relationship paths that produce unexpected filtering.'],
 ['A date table supports consistent time analysis.','It supplies continuous dates and fields such as year and month. Sort month names by a numeric month field, not alphabetically.'],
 ['Not every number should be summed.','Prices, rates and end-of-period balances need appropriate calculations. Revenue totals and average prices answer different questions.']
],['Revenue by product category','An order-line fact table links to a unique Product dimension, which contains category. A Date dimension supplies months. This supports consistent category and time filters across visuals.'], 'Draw a star with OrderLines in the middle and Products, Customers and Dates around it. Mark the grain and relationship keys.', ['Which is usually a dimension attribute?',['Product category','Order-line revenue','Units sold on a line'],0,'Category describes the product; revenue and units are event measurements.'], 'A trustworthy dashboard rests on a trustworthy model.','star');
L(4,'Calculate metrics in context','Understand what a calculation includes when the reader changes a filter.',[
 ['A metric needs a business definition.','“Revenue” might mean paid sales excluding tax and refunds. Agree on that definition before writing a formula.'],
 ['Power BI measures respond to filter context.','A DAX measure such as SUM of revenue changes with the selected month or category. Calculated columns are evaluated differently and stored with rows.'],
 ['Tableau calculations have different levels.','Row-level calculations, aggregate calculations, table calculations and level-of-detail expressions answer different types of questions.'],
 ['Ratios need appropriate aggregation.','Total profit divided by total revenue gives overall margin. Averaging row-level margins equally can produce a different result.'],
 ['Test totals and individual slices.','Check one product, one month and the all-data total. Different contexts can expose definition or relationship mistakes.']
],['Overall margin is a weighted result','One sale earns 5 profit on 10 revenue; another earns 10 on 100. Overall margin is 15 ÷ 110 ≈ 13.6%, not the simple average of 50% and 10%.'], 'Define a conversion rate with a clear numerator and denominator. Explain how the period filter should affect both.', ['Overall profit margin should usually be calculated as…',['Average of every row’s margin regardless of size','Total profit divided by total revenue','Total revenue minus customer count'],1,'This weights the combined result by the actual revenue behind each row.'], 'A metric is a definition plus a calculation plus its filter context.','bars','// Power BI DAX\nRevenue = SUM(OrderLines[Revenue])\n\n// Concept shared across tools\nOverall margin = Total profit / Total revenue');
L(4,'Choose charts people can read','Match each visual to the comparison and remove unnecessary effort.',[
 ['Bars compare categories.','Sort deliberately and use a zero baseline for ordinary bar charts so lengths communicate magnitude honestly.'],
 ['Lines reveal change over time.','Use a meaningful time axis and consistent intervals. Show or explain missing periods rather than connecting them silently.'],
 ['Scatter plots compare numeric variables.','They reveal relationships, clusters and unusual observations. They do not by themselves establish a causal link.'],
 ['Use color with purpose.','Reserve emphasis for what matters. Pair color with labels or symbols so meaning is not dependent on color vision alone.'],
 ['Label the metric and its units.','Include currency, period and whether a rate is a percentage. Titles can express the finding when the evidence supports it.']
],['An easy product comparison','Compare five product revenues with sorted horizontal bars. Start the bars at zero and show currency. A 3D pie would make close values harder to compare without adding useful evidence.'], 'Choose a chart for monthly sales, revenue by product and order value versus delivery time. Explain each choice.', ['Which is a good starting chart for revenue across five products?',['A sorted bar chart','A decorative 3D sphere','A line joining unrelated product names'],0,'Bar lengths support direct category comparison.'], 'A good chart reduces the effort needed to understand a comparison.','bars');
L(4,'Make dashboards interactive and accessible','Help readers explore without losing the question or context.',[
 ['Filters change the visible data scope.','Make the selected period and segment obvious. Provide a simple route back to the default view.'],
 ['Drill-down moves to finer detail.','Year to month or category to product can reveal a driver. Keep the reader aware of the current level.'],
 ['Tooltips add supporting detail.','They should supplement visible information, not hide essential units or definitions. Touch and keyboard users also need access to key facts.'],
 ['Layout establishes reading order.','Put the main question and headline metric first, then supporting comparisons and detail. Test on the device people will actually use.'],
 ['Accessibility is part of readability.','Use readable text, sufficient contrast, clear labels and non-color cues. Avoid tiny controls and crowded chart legends.']
],['A filter with consequences','A dashboard shows revenue for all products. Selecting “Tea” should update relevant metrics and display the active selection. If one chart intentionally ignores that filter, label the exception clearly.'], 'Sketch a phone-sized dashboard. Include a period filter, one headline number and one supporting comparison without tiny text.', ['Where should essential metric definitions live?',['Only in a mouse-hover tooltip','In visible or otherwise accessible supporting information','Nowhere if the chart is attractive'],1,'Essential information must remain available to touch, keyboard and assistive-technology users.'], 'Interaction should clarify the analysis, not make the reader guess what changed.','dashboard');
L(4,'Publish a report people can trust','Check accuracy, access and freshness before handing it over.',[
 ['Reconcile the important numbers.','Compare dashboard totals with independent source calculations. Test filters and totals rather than only the initial view.'],
 ['Refresh needs ownership.','Set an appropriate schedule and identify who monitors failures. Show the data’s freshness when it matters to decisions.'],
 ['Share with the right audience.','Check permissions and sensitive fields. Row-level security can restrict records by viewer, but must be tested as the intended user.'],
 ['Performance affects usability.','Reduce unnecessary visuals and expensive calculations. Test loading and interaction with realistic data volume.'],
 ['Document and hand over.','Provide definitions, sources, known limitations and a contact for issues. A dashboard without maintenance can become stale evidence.']
],['The number is correct, but old','A report may accurately show last month’s data while a reader assumes it reflects yesterday. Display a clear “data through” timestamp and investigate refresh failures.'], 'Make a release checklist covering totals, filters, permissions, mobile readability, refresh and metric definitions.', ['What does a successful report refresh prove?',['Every metric is correct','The refresh ran; accuracy still needs validation','Every viewer can see the same data'],1,'Refresh success does not verify business definitions, relationships or permissions.'], 'A report is ready when its numbers, context, access and maintenance are all understood.','workflow');
// STAGE 6
L(5,'Profile before you change anything','Understand the source and record what good data should look like.',[
 ['Create a small data dictionary.','Record each field’s meaning, type, units, allowed values and source owner. Names alone rarely explain everything.'],
 ['Confirm the grain and expected key.','State what one row represents and what uniquely identifies it. This guides duplicate checks and joins.'],
 ['Profile completeness and validity.','Count missing fields, inspect value ranges and compare types with expectations. Sample records as well as summary numbers.'],
 ['Look for collection changes.','A new tracking system, revised form or changed definition can create artificial trends. Ask how the data was generated.'],
 ['Preserve a raw reference.','Keep inputs unchanged and produce a separate cleaned result. Record the source period and extraction time.']
],['A suspiciously clean rating field','A rating column contains only 1–5, but missing ratings were imported as 5. A range check passes while the meaning is wrong. Source documentation and missingness rules reveal the issue.'], 'Write a data dictionary for OrderID, OrderDate, Quantity and Revenue. Include one validity rule for each.', ['What should happen before removing unusual rows?',['Understand the source, grain and validity rules','Sort them out of view','Change them to average values'],0,'You need context to distinguish errors from legitimate observations.'], 'Profiling is learning what the dataset means before deciding how to change it.','sheet');
L(5,'Missing values are a question','Choose a treatment based on why the information is absent.',[
 ['Missing has several meanings.','Not collected, not applicable, unknown and not yet available may require different treatments. Preserve meaningful distinctions.'],
 ['Measure where missingness occurs.','Report counts and rates by field, period and group. Missing data concentrated in one channel can bias comparisons.'],
 ['Dropping rows changes the population.','It can be reasonable for a specific task, but describe what you excluded and whether the remaining data is representative.'],
 ['Imputation makes assumptions.','Filling with a mean, median or another estimate changes distributions and uncertainty. Do not treat filled values as observed truth.'],
 ['Zero is a real value.','A missing sale is not automatically a sale of zero. Use explicit flags or separate categories when absence is meaningful.']
],['Missing delivery times','If delayed shipments are more likely to lack a recorded delivery time, analyzing only complete deliveries makes performance look better. Investigate the collection process before presenting an average.'], 'For missing customer age, missing revenue and a blank optional comment, suggest different handling rules and justify them.', ['Why might deleting all incomplete records create bias?',['Missingness may be related to the outcome','It always increases accuracy','Missing values are always random'],0,'The excluded records may differ systematically from the records you keep.'], 'Treat missingness as information about the data collection process.','sample');
L(5,'Duplicates, types & inconsistent labels','Standardize carefully while preserving information.',[
 ['A repeated row is not always a duplicate event.','Two identical purchases may be real. Define the business key and investigate whether the source imported an event twice.'],
 ['IDs are labels, even when they contain digits.','Converting “0012” to 12 can lose meaning or break joins. Store identifiers according to their definition.'],
 ['Standardize category labels.','Trim spaces, normalize case and use an approved mapping for variants. Do not merge genuinely different categories because they look similar.'],
 ['Dates and units need consistency.','Know whether 03/04 means March 4 or April 3. Convert currencies and measurements using documented rates and reference times.'],
 ['Preserve raw values when useful.','Keep an original column alongside the standardized column and record transformation rules. This makes corrections traceable.']
],['Coffee, coffee and “ coffee ”','These may be the same product label, so trimming and case normalization help. “Coffee large” could be a distinct product and should not be merged without business confirmation.'], 'Define a duplicate rule for an order-line dataset. Explain how you would distinguish a repeated import from two genuine identical purchases.', ['Which field should often remain text?',['A product ID with meaningful leading zeros','A quantity to sum','A numeric price for calculation'],0,'Identifiers can contain meaningful formatting that numeric conversion would discard.'], 'Standardization should resolve inconsistency without erasing valid distinctions.','sheet');
L(5,'Join, reshape & handle outliers safely','Structural changes deserve checks, not just a successful command.',[
 ['Choose joins based on the question.','Decide which unmatched records to retain and validate expected cardinality. Measure unmatched keys and duplicated outputs.'],
 ['Track row counts at each step.','A filter should reduce or preserve rows, while a join may increase them. Unexpected changes need explanation before proceeding.'],
 ['Reshape without changing meaning.','Unpivot repeated month columns into Month and Revenue. Check that the total is unchanged and labels remain accurate.'],
 ['Investigate extreme observations.','Check units, source records and business context. An outlier can be a real high-value customer or an input error.'],
 ['Document any treatment.','Correct verified errors at the source if possible. If excluding or capping values for a particular analysis, justify the rule and compare its effect.']
],['A hundredfold price difference','A price of 1,200 among values near 12 may be cents mixed with dollars. It might also be a real premium item. Check the product and source units before dividing by 100.'], 'List checks before and after merging a product table into orders. Include unmatched IDs, row counts and revenue totals.', ['An unusually large value should be…',['Deleted immediately','Investigated before treatment','Changed to the median automatically'],1,'Unusual values can be valid or erroneous; context determines the action.'], 'A transformation is complete only when its effect has been checked.','join');
L(5,'Build a small quality checklist','Translate “looks okay” into checks you can repeat.',[
 ['Completeness checks required information.','For example, every paid order needs an OrderID and amount. Not every optional field needs to be populated.'],
 ['Uniqueness checks the intended key.','An order-line key may be OrderID plus LineNumber, not OrderID alone. Confirm the expected grain.'],
 ['Validity checks allowed values.','Examples include nonnegative quantities, supported currencies and valid dates. Business rules can have legitimate exceptions.'],
 ['Consistency compares related fields.','A delivery should not precede its order. Line totals should reconcile with order totals under the documented tax and discount rules.'],
 ['Freshness checks timeliness.','Compare the newest record and extraction time with expectations. Log failures with enough detail for investigation rather than silently dropping records.']
],['A tiny quality report','For 1,000 order lines: missing IDs = 0, duplicate line keys = 2, unsupported currency = 1. Investigate those records before deciding whether the report is reliable enough to publish.'], 'Create six pass/fail checks for your order dataset. For each, specify what should happen when the check fails.', ['Which is the best uniqueness key for order lines?',['OrderID automatically','The key defined by the grain, often OrderID + LineNumber','Customer name'],1,'A customer or order may appear on several valid lines. The key must identify a single line.'], 'Repeatable checks turn data quality into visible evidence.','workflow');
L(5,'Privacy, provenance & a clean handover','Make the cleaned dataset safe and understandable for the next person.',[
 ['Collect and share only what is needed.','A revenue analysis may not require names, full addresses or other personal details. Minimize sensitive fields.'],
 ['Masking is not always anonymization.','Removing names may still leave identifying combinations. Use approved access and handling practices for your context.'],
 ['Record provenance.','Document sources, extraction time, transformations and known issues. A result should be traceable to its inputs.'],
 ['Separate raw, cleaned and output data.','Use clear names and avoid overwriting inputs. Reproducible steps are more useful than an unexplained final file.'],
 ['Describe fitness for use.','A dataset may support product totals but not accurate customer demographics. State the limitations relevant to the planned decision.']
],['An unnecessary customer export','To compare revenue by product category, export category, date and amounts rather than every customer’s contact details. Restrict source access and share the smallest useful output.'], 'Write a handover note containing source, grain, key, cleaning rules, validation results, sensitive fields and limitations.', ['What is the safest useful dataset to share for category revenue analysis?',['Every customer detail just in case','The minimum fields needed for the analysis','An unprotected full database backup'],1,'Minimizing data reduces unnecessary exposure while preserving analytical usefulness.'], 'A trustworthy dataset has context, traceability and appropriate access.','workflow');
// STAGE 7
L(6,'Turn a vague request into a question','Define a decision, a metric and a comparison before exploring.',[
 ['Start with the decision owner.','Ask who will act on the findings and what options they have. This prevents an analysis that is interesting but unusable.'],
 ['Define the metric precisely.','“More customers” could mean visitors, new purchasers or active subscribers. Specify the unit, period and inclusion rules.'],
 ['Choose a relevant baseline.','Last week, the same month last year, a target or a comparable group can each tell a different story.'],
 ['Break the question into drivers.','Revenue can be decomposed into orders × average order value. Orders can be related to visitors × conversion, with aligned definitions.'],
 ['State a hypothesis, not a conclusion.','“Fewer visitors may explain the revenue decline” is something to test, not something to assume.']
],['“Sales are bad” becomes answerable','Ask: “Which product groups explain the fall in paid net revenue this month versus the same month last year?” Define refunds, currency and complete periods before calculating.'], 'Rewrite “customers are unhappy” as an answerable question. Specify a decision, metric, population, period and comparison.', ['What makes a business question analytical?',['It names a measurable issue and relevant comparison','It includes as many tools as possible','It already states the preferred answer'],0,'A clear scope and comparison turn a concern into something evidence can address.'], 'A well-defined question saves more effort than a complicated technique.','workflow');
L(6,'Explore one variable, then relationships','Use summaries and plots to understand structure before explaining it.',[
 ['Univariate exploration examines one variable.','Look at counts for categories and distributions for numeric values. Include missing values and unexpected categories.'],
 ['Bivariate exploration compares two variables.','Use scatter plots for two numeric fields or grouped summaries for category-to-number comparisons.'],
 ['Multivariate views add context.','Compare a relationship across channel, region or period. Keep groups large enough for meaningful interpretation.'],
 ['Aggregation can hide reversals.','An overall result may differ from within-group results because group proportions change. Inspect important segments before drawing conclusions.'],
 ['Exploration generates hypotheses.','Looking at many comparisons can find chance patterns. Confirm important findings with appropriate methods or fresh data where possible.']
],['The overall average hides the mix','Average order value rises overall, but stays flat within both retail and wholesale. A larger share of wholesale orders could explain the increase without any within-channel improvement.'], 'Choose one numeric and one categorical field. Plan three plots or summaries and explain what each would help you inspect.', ['An overall average changes while each segment stays flat. What should you examine?',['The mix of segment sizes','Only the chart color','Whether averages are forbidden'],0,'Changing group weights can change the overall average even when segment averages do not move.'], 'Look at both the whole dataset and meaningful groups.','distribution');
L(6,'Trends, seasonality & fair comparisons','Understand time patterns before calling a change unusual.',[
 ['Trend is a longer-term movement.','Seasonality is a repeating pattern, such as higher weekend demand. Random variation can sit on top of both.'],
 ['Compare complete and comparable periods.','A half-finished month should not be compared directly with a full month. Adjust for working days when relevant.'],
 ['Moving averages smooth variation.','They make patterns easier to see but can hide sudden changes and lag behind events. State the window used.'],
 ['Missing time points need interpretation.','A blank day could mean no orders, a closed shop or a broken feed. Do not automatically fill every gap with zero.'],
 ['Events can explain context, not prove cause.','Annotate promotions, holidays and system changes. Investigate competing explanations before making causal claims.']
],['A Monday is not a Saturday','Revenue on Monday falls relative to Saturday, but matches prior Mondays. A day-of-week comparison provides a more useful baseline than treating all daily changes as equal.'], 'Design a comparison for this week’s sales while the week is still in progress. Describe how you would align days and account for holidays.', ['Which comparison is usually fairer for an incomplete month?',['Month-to-date versus a full previous month','Comparable elapsed periods with context','Any period with the biggest total'],1,'Aligned periods reduce differences caused simply by unequal time coverage.'], 'A meaningful time comparison respects calendars, completeness and recurring patterns.','trend');
L(6,'Segments, cohorts, funnels & retention','Understand how groups move through a process and change over time.',[
 ['Segments group records by attributes.','Examples include region, channel or product category. Choose groups linked to a decision rather than arbitrary slices.'],
 ['Cohorts group people by a shared start.','A signup-month cohort lets you compare customers at the same age since joining, instead of mixing new and mature users.'],
 ['Funnels describe ordered steps.','For example: visit → add to cart → pay. Define whether steps must occur in order and within a time window.'],
 ['Retention depends on its definition.','Specify who is eligible, what counts as returning and how long you observe them. Do not compare a fully observed cohort with an immature one.'],
 ['Rates need stable denominators.','A funnel step rate and an overall conversion rate use different bases. Show counts alongside percentages when groups are small.']
],['A new cohort needs time','Customers who signed up yesterday cannot yet have 30-day retention measured. Comparing their incomplete outcome with a three-month-old cohort would confuse observation time with behavior.'], 'Define a three-step checkout funnel. Write the numerator and denominator for each step rate and the overall purchase rate.', ['Why compare cohorts at the same age?',['To avoid unequal observation time','To guarantee identical behavior','To remove every source of bias'],0,'Equivalent time since joining makes the available follow-up more comparable.'], 'Define who entered, what counts as progress and how long you observed them.','funnel');
L(6,'Use tests and regression responsibly','Choose a method that matches the question and its assumptions.',[
 ['Match the test to the data.','A mean, a proportion and a category relationship require different approaches. Consider independence, sample size and distributional assumptions.'],
 ['Interpret size and uncertainty together.','An interval can show both plausible improvement and plausible harm. Statistical significance does not measure business importance.'],
 ['Regression models a conditional relationship.','A coefficient describes an estimated association while holding included variables fixed. Omitted factors can still bias interpretation.'],
 ['Check model assumptions and residuals.','Look for systematic patterns, unstable estimates and influential observations. A good-looking line does not prove an adequate model.'],
 ['Avoid selective reporting.','Trying many comparisons and presenting only the smallest p-value inflates false discoveries. Plan primary questions and disclose exploration.']
],['A small but expensive lift','A checkout change improves conversion by 0.05 percentage points with a narrow uncertainty interval. If development and support costs exceed the likely benefit, the change may not be worthwhile despite strong statistical evidence.'], 'Write a conclusion for a test whose estimated lift is positive but whose interval includes a meaningful decline. Avoid saying the change definitely works.', ['A regression coefficient automatically proves causation.',['Yes','No; design and confounding still matter','Only if the software is expensive'],1,'Regression can adjust for included variables but does not by itself establish a causal mechanism.'], 'Use models as structured evidence, with assumptions and practical consequences.','experiment');
L(6,'Your first end-to-end analysis','Bring the skills together into a small, defensible project.',[
 ['Choose a bounded question.','Use a public, synthetic or otherwise authorized dataset. A clear small project is stronger than a huge unfocused one.'],
 ['Audit and clean the inputs.','Document grain, missing values, duplicates, keys and exclusions. Keep a traceable sequence of transformations.'],
 ['Analyze against your question.','Calculate the main metric, compare a baseline and investigate a few plausible drivers. Avoid adding unrelated charts.'],
 ['Check the conclusion.','Reconcile totals, review counterexamples and explain uncertainty. Separate evidence from assumptions and ideas requiring further testing.'],
 ['Deliver an actionable recommendation.','State what to do, why, potential downsides and what metric to monitor next. Keep your analysis reproducible.']
],['A café project brief','Investigate which products account for a revenue decline. Compare aligned months, decompose orders and order value, inspect category mix and check refunds. Recommend a next step without claiming the data proves a cause it cannot identify.'], 'Create a one-page project outline: question, dataset, checks, three analyses, likely limitations and the decision your results will support.', ['What makes a portfolio project convincing?',['Many screenshots without context','A clear question, reproducible work and defensible conclusions','A complicated model regardless of purpose'],1,'A reviewer should understand the problem, your reasoning, your checks and the usefulness of the result.'], 'A complete project demonstrates judgment as well as tool use.','workflow');
// STAGE 8 — optional, honestly scoped.
L(7,'What machine learning adds','Understand when prediction helps and when a simpler analysis is enough.',[
 ['This stage is an optional extension.','Many analyst roles focus on SQL, spreadsheets, dashboards and communication. Machine learning is useful when the problem genuinely needs prediction or pattern discovery.'],
 ['Supervised learning uses labeled examples.','A numeric target suggests regression; a category target suggests classification. Features are the information available to make the prediction.'],
 ['Unsupervised learning explores structure.','Clustering groups similar observations without known target labels. The groups still need business interpretation.'],
 ['A prediction is not a causal claim.','A feature can help predict an outcome without being something you should change to cause improvement.'],
 ['Define the action first.','Specify who will use the prediction, when it is available and the cost of mistakes. This determines whether a model is useful.']
],['Predicting late delivery','At dispatch time, use information already known to estimate whether delivery will be late. The model might help prioritize checks, but predicted risk alone does not explain the cause of a delay.'], 'Name one regression task, one classification task and one problem that needs only a simple descriptive report.', ['Predicting a numeric delivery duration is usually…',['Regression','Classification of product names','Proof of causation'],0,'Regression predicts a numeric outcome; classification predicts categories.'], 'Use machine learning for a defined prediction task, not as decoration.','nodes');
L(7,'Split data and prevent leakage','An honest evaluation imitates the situation in which predictions will be used.',[
 ['Training data fits the model.','Validation data helps choose settings. Test data supports a final evaluation and should not become another tuning set.'],
 ['Leakage uses information unavailable at prediction time.','A delivery completion timestamp cannot help a model meant to predict lateness at dispatch. It reveals the future.'],
 ['Time-based tasks need time-aware splits.','Train on earlier records and evaluate on later records when forecasting future outcomes. Random splitting can give an unrealistic advantage.'],
 ['Related entities can also leak.','Records from the same customer or device may need grouped splitting. Otherwise the model may recognize entities rather than generalize.'],
 ['Fit preprocessing on training data only.','Learn scaling, imputation and encoding rules from training data and apply them to held-out data. Pipelines help enforce this separation.']
],['The almost-perfect model','A churn model includes AccountClosedDate while claiming to predict churn before it happens. That field gives away the result. Remove it and reassess using only information available at the decision time.'], 'For predicting next month’s purchases, choose a train/test split and list three fields that could accidentally reveal future information.', ['Which field leaks future information for a dispatch-time lateness model?',['Distance known at dispatch','Actual delivery completion time','Dispatch weekday'],1,'The completion time is unavailable when the prediction is supposed to be made.'], 'An impressive score is meaningless if the model can see the answer.','experiment');
L(7,'Preprocessing and your first baseline','Build a simple, repeatable model before adding complexity.',[
 ['Start with a baseline.','Predicting the historical mean for a numeric target or a simple class rule gives a reference. A model must beat a relevant baseline to add value.'],
 ['Handle missing features consistently.','Choose a justified strategy, fit it on training data and retain information about meaningful missingness where appropriate.'],
 ['Encode categories for the estimator.','One-hot encoding is a common starting point. Consider how unseen categories will be handled during future use.'],
 ['Scale when the method needs it.','Distance-based methods and some regularized models are sensitive to scale. Tree-based methods often do not require standard scaling.'],
 ['Use scikit-learn pipelines.','A pipeline packages preprocessing and estimation so the same learned steps apply during validation and prediction.']
],['A baseline can be hard to beat','If daily demand is strongly seasonal, yesterday’s demand may be a weaker baseline than the same weekday last week. Choose a baseline that reflects the actual business setting.'], 'Propose a simple baseline for predicting café sales and another for predicting late deliveries. Explain their limitations.', ['Where should preprocessing parameters be learned?',['From the entire dataset before splitting','From training data only','From the final test labels'],1,'Learning from held-out data can leak information into the evaluation.'], 'Build a credible baseline and a repeatable pipeline before a complex model.','workflow');
L(7,'Meet a few useful model families','Understand what models do before adjusting their settings.',[
 ['Linear regression predicts numeric values.','It combines feature contributions in a linear form. Check assumptions and whether the relationship is suitable.'],
 ['Logistic regression estimates class probabilities.','Despite its name, it is commonly used for classification. A probability threshold converts an estimate into an action.'],
 ['Decision trees split observations using rules.','They can model nonlinear patterns but may overfit if allowed to grow too deeply.'],
 ['Random forests combine many trees.','They often improve stability but can be harder to explain. More complexity is not automatically more useful.'],
 ['K-means groups by distance.','Scaling and the chosen number of clusters matter. A cluster label is not automatically a real customer “type.”']
],['A useful first comparison','For predicting a numeric order value, compare a baseline, a linear model and a restrained tree. Use the same validation approach and metric, and inspect errors rather than choosing the most complicated name.'], 'Match numeric demand, refund risk and customer grouping to suitable model families. Explain what output each gives.', ['Despite its name, logistic regression is commonly used for…',['Classification','Only sorting spreadsheet rows','Database indexing'],0,'It estimates probabilities for classes, often a binary outcome.'], 'Choose a model by its task, assumptions, performance and interpretability.','nodes');
L(7,'Evaluate errors that matter','Choose metrics that reflect the costs of being wrong.',[
 ['MAE averages absolute numeric errors.','It stays in the target’s units. RMSE penalizes larger numeric errors more strongly. Compare against a baseline.'],
 ['Classification has different error types.','A false positive flags a case incorrectly; a false negative misses a real case. A confusion matrix makes them visible.'],
 ['Precision and recall answer different questions.','Precision asks how many flagged cases are truly positive. Recall asks how many actual positives were found.'],
 ['Accuracy can hide class imbalance.','If only 1% of orders are fraudulent, predicting “not fraud” always gives 99% accuracy but catches none of the fraud.'],
 ['Thresholds express tradeoffs.','Lowering a risk threshold often raises recall while lowering precision. F1 combines precision and recall, but may not match the real financial or operational cost.']
],['A fraud alert team has limited time','The model flags 100 orders, 20 of which are fraudulent: precision is 20%. If there are 40 fraud cases in total, recall is 50%. Whether that is useful depends on review capacity and the cost of missed fraud.'], 'Calculate precision and recall if 30 alerts contain 12 true cases and there are 20 actual cases. Explain which error matters most in your chosen scenario.', ['An all-negative model scores 99% accuracy on data with 1% positives. Its positive recall is…',['99%','100%','0%'],2,'It finds none of the actual positives, so recall is zero.'], 'Evaluate the errors the business cares about, not just the easiest score.','matrix');
L(7,'Validate, explain and know when to stop','A good model remains useful beyond the dataset where it was built.',[
 ['Overfitting learns training-specific patterns.','Very strong training results with weaker held-out results are a warning. Simpler models or regularization may help.'],
 ['Cross-validation supports more stable comparisons.','Use a method appropriate to time and grouped observations. Keep the final test separate from repeated tuning.'],
 ['Tune a limited, justified set of settings.','More search can overfit the validation process. Record what you tried and compare with the baseline.'],
 ['Interpret explanations cautiously.','Feature importance is model- and method-dependent. Correlated features and leakage can distort apparent importance; importance does not prove causality.'],
 ['Monitor after use.','Input distributions, data quality and outcomes can change. Define monitoring, ownership and when to fall back or retrain.']
],['Great last year, poor this year','A shipping policy changes and customer behavior shifts. The previous model may no longer reflect the new setting. Monitor performance on new outcomes and inspect whether data definitions also changed.'], 'Write a brief model handover: purpose, available inputs, baseline, evaluation, errors, limitations and monitoring plan.', ['High feature importance proves that changing that feature will change the outcome.',['True','False; predictive importance is not a causal effect','Only for a random forest'],1,'Importance describes a model’s behavior, not the result of an intervention.'], 'A model earns trust through honest evaluation, clear limits and ongoing monitoring.','workflow');
// STAGE 9
L(8,'Find the message behind the analysis','Make the answer clear before deciding how to present it.',[
 ['Know the audience’s decision.','An operations lead needs a different level of detail from someone reviewing your methodology. Adapt the explanation without changing the evidence.'],
 ['Lead with the useful finding.','State the result in plain language, then show supporting evidence. Avoid making the reader reconstruct the point from a sequence of screenshots.'],
 ['Separate fact, interpretation and recommendation.','“Revenue fell 8%” is a finding. “Stockouts may explain it” is an interpretation. “Check availability on top products” is a proposed action.'],
 ['Keep scope and uncertainty visible.','Name the period, population and important limitations. Do not turn exploratory associations into confident causal statements.'],
 ['Use a simple narrative.','Question → evidence → meaning → next action is often enough. Include details only when they help assess the conclusion.']
],['A clearer opening','Instead of “I used SQL and made six charts,” say “Paid revenue fell 8% versus the same month last year, concentrated in two product categories. Stock availability is a plausible driver that needs checking.”'], 'Write a two-sentence opening for a report about a revenue decline. Label one finding and one uncertainty.', ['Which is an interpretation rather than an observed fact?',['Revenue fell 8%','There were 200 paid orders','Stockouts may explain the decline'],2,'The suggested explanation needs additional evidence; it is not the same as the measured change.'], 'Make it easy to distinguish what you know from what you suspect.','message');
L(8,'Make charts tell the truth clearly','Use titles, scales and annotations to reduce misunderstanding.',[
 ['Choose the comparison first.','Category ranking, time change, distribution and relationships require different visual forms.'],
 ['Write informative titles.','“Two categories account for most of the decline” is more useful than “Chart 4” if the analysis supports it. Add a descriptive subtitle when needed.'],
 ['Label units, period and source.','A percentage without a denominator or a currency amount without a period lacks essential context.'],
 ['Use honest scales.','Ordinary bar charts need a zero baseline. A limited line-chart axis can be useful, but should be clear and not exaggerate the interpretation.'],
 ['Annotate sparingly and accessibly.','Highlight the relevant value or event, use readable text and pair color with labels. Remove decoration that competes with the evidence.']
],['A small change made to look huge','Two bars representing 98 and 100 look dramatically different if the axis begins at 97. Starting ordinary bars at zero preserves meaningful length comparison; exact labels can show the small difference.'], 'Draft a chart title, subtitle, axes and one annotation for monthly revenue. Include currency, period and the comparison baseline.', ['Why do ordinary bar charts usually start at zero?',['Bar length represents magnitude','Zero makes every metric correct','All chart types always require zero'],0,'A truncated baseline distorts the ratio communicated by bar lengths.'], 'Visual clarity and honesty are part of analytical accuracy.','bars');
L(8,'Turn a finding into a useful action','Recommendations should acknowledge costs, alternatives and what happens next.',[
 ['Connect action to evidence.','Explain which finding supports the recommendation. If evidence is weak, suggest a targeted investigation or small experiment.'],
 ['Name the owner and next step.','A specific request such as “Operations checks availability for the top five products” is easier to act on than “Improve sales.”'],
 ['Consider tradeoffs and constraints.','A discount might increase orders but reduce margin. A faster delivery promise may increase cost or failures.'],
 ['Estimate impact transparently.','Use a range and state assumptions. Do not present a scenario as a guaranteed forecast.'],
 ['Define follow-up measurement.','Choose a success metric, a risk metric and an evaluation period. Decisions create new evidence for the next analysis.']
],['A practical stock recommendation','Recommend checking availability on products responsible for the largest decline, then piloting improved restocking in a few locations. Track paid revenue and margin, not revenue alone, and compare with a suitable baseline.'], 'Write a recommendation with an owner, next action, evidence, downside and success measure. State one assumption that could change it.', ['Which recommendation is most actionable?',['Improve everything','Check top-product availability, pilot a change and monitor revenue plus margin','Build more charts'],1,'It gives an explicit action and a way to assess benefits and tradeoffs.'], 'A useful recommendation includes the action and how to learn whether it worked.','workflow');
L(8,'Write and present with confidence','Organize the details so a reader can understand and challenge your work.',[
 ['Use an answer-first summary.','Open with the question, main finding and recommendation. Keep technical methods in supporting sections when the audience does not need them upfront.'],
 ['Use short, meaningful points.','One idea per bullet is easier to follow. Explain unfamiliar terms and avoid replacing a clear word with jargon.'],
 ['Structure a presentation around decisions.','Each slide should have a purpose and a message. Use a small number of relevant visuals rather than showing every exploratory chart.'],
 ['Invite and handle questions honestly.','Clarify the question, point to evidence and acknowledge what was not tested. It is acceptable to propose a follow-up check.'],
 ['Make the work reviewable.','Include definitions, sources, methods and limitations in an appendix or linked material. Check that shared files do not expose sensitive data.']
],['A five-part report','Use: 1) question and decision, 2) key finding, 3) supporting evidence, 4) limitations, 5) recommendation and next measurement. Add query or cleaning details separately so reviewers can verify the work.'], 'Prepare a 60-second explanation of a small analysis. Ask someone to repeat the main finding and proposed action back to you.', ['If asked a question your analysis did not test, you should…',['Invent a confident answer','State the limit and propose how to investigate','Change the chart title'],1,'Honest boundaries maintain trust and turn an unknown into a useful follow-up.'], 'Confidence comes from knowing your evidence and its limits.','message');
L(8,'Build a portfolio with evidence','Show your judgment through complete, understandable case studies.',[
 ['Select a few focused projects.','Cover a spreadsheet or SQL analysis, a dashboard and an end-to-end investigation. Choose questions that genuinely interest you.'],
 ['Show the starting problem.','Describe the audience, decision, source and data grain. Make clear whether data is public or synthetic.'],
 ['Include meaningful technical evidence.','Share readable queries, transformation steps and checks. Explain important choices rather than pasting everything you tried.'],
 ['Communicate findings and limitations.','Use a few clear visuals and an action-oriented summary. Do not claim actual business impact unless the action was implemented and measured.'],
 ['Make reproduction possible.','Provide allowed data or clear access instructions, dependencies and steps. Remove secrets and personal information before sharing.']
],['A credible project claim','Say “Identified two categories contributing 70% of the observed decline and proposed an availability check,” rather than “Increased sales 70%” when no intervention was performed.'], 'Outline three portfolio projects. For each, list the question, tools, checks, final visual and what skill the project demonstrates.', ['Which project statement is honest without measured implementation?',['My dashboard increased revenue by 30%','I identified a pattern and proposed a testable action','My model guarantees success'],1,'Proposals and findings should not be presented as verified real-world outcomes.'], 'A portfolio demonstrates how you reason, validate and communicate.','dashboard');
L(8,'From learning to real analyst work','Use a practical readiness checklist and keep building experience.',[
 ['Knowledge is the beginning.','Reading builds understanding; doing tasks without copying, handling messy data and getting feedback build working ability. No course guarantees perfect job readiness.'],
 ['Check core technical independence.','Can you clean a file, write joins and grouped SQL, validate results and build a readable report with one dashboard tool?'],
 ['Check analytical judgment.','Can you define a metric, choose a comparison, investigate an unexpected result and explain uncertainty without overstating cause?'],
 ['Practise realistic communication.','Explain a project in a few minutes, answer questions and document assumptions. Rehearse SQL and business cases using unfamiliar examples.'],
 ['Keep a learning loop.','Use projects and feedback to identify gaps. Return to relevant lessons, practise the skill and reassess. Machine learning remains optional for many analyst paths.']
],['Your final capstone','Analyze an authorized sales dataset from question to recommendation. Deliver a cleaned table, documented SQL or Python, a small dashboard and a one-page brief. Ask a reviewer to reproduce one result and challenge your main conclusion.'], 'Complete a capstone without following a step-by-step solution. Score yourself on question clarity, data quality, correct analysis, clear visuals and defensible recommendations.', ['What best demonstrates readiness beyond lesson completion?',['A full progress bar alone','Independent, validated projects and clear explanations','Memorizing every library name'],1,'Applied work and feedback show whether you can use the knowledge reliably in new situations.'], 'Keep learning, but measure progress through work you can independently explain and defend.','workflow');
window.CURRICULUM={stages,lessons};
